-- Activities that need a licence or a registry entry of their own. The list of
-- activities and why each needs a licence lives in lib/activities.ts; here are
-- the licence services (documents and stages) and what each company has said.

alter table public.services drop constraint services_kind_check;
alter table public.services add constraint services_kind_check check (kind in ('founding', 'compliance', 'renewal', 'amendment', 'closure', 'license'));

-- null: not asked yet; empty: none of the listed activities.
alter table public.companies add column activities text[];

-- What the owner said about a licensed activity: already licensed, or it does not apply.
create table public.activity_status (
  company_id uuid not null references public.companies(id) on delete cascade,
  activity_id text not null,
  status text not null check (status in ('have', 'na')),
  set_at timestamptz not null default now(),
  primary key (company_id, activity_id)
);
alter table public.activity_status enable row level security;
create policy activity_status_owner on public.activity_status for all to authenticated
  using ((select public.owns_company(company_id))) with check ((select public.owns_company(company_id)));
grant select, insert, update, delete on public.activity_status to authenticated;

